  "3 à 16 lettres ou chiffres": "3 to 16 letters or digits",
  "8 caractères, Aa1 et symbole": "8 characters, Aa1 and a symbol",
  ": Attire sur elle toutes les attaques du prochain tour ennemi, se met en Défense et se donne un bouclier.": ": Draws every attack of the next enemy turn onto itself, goes into Defense and gains a shield.",
  ": Elle entre avec un bouclier qui bloque le prochain coup.": ": It enters with a shield that blocks the next hit.",
  ": Engloutir, Augure": ": Engulf, Augury",
