  "<b>Marque</b> : le prochain coup d’une <b>autre</b> de tes créatures fait +{0} % et +{1} Brisure, puis elle part. Garde-la pour ton plus gros coup.": "<b>Mark</b>: the next hit from <b>another</b> of your creatures deals +{0}% and +{1} Break, then it fades. Save it for your biggest hit.",
