  "<b>Tu as atteint le fond de l’Abysse !</b> Le Booster de l’Abysse t’attend dans les Boosters.": "<b>You've reached the bottom of the Abyss!</b> The Abyss Booster awaits you in Boosters.",
  "<b>T’arrêter</b>{e0}": "<b>Stopping</b>{e0}",
