  "<b>Vaincs La Matriarche du Givre</b>{e0}": "<b>Defeat the Frost Matriarch</b>{e0}",
  "<b>Victoire · étage {0}</b>{e0}": "<b>Victory · floor {0}</b>{e0}",
  "<b>Voir une carte</b> : garde le doigt appuyé sur une carte (ennemie ou alliée) pour ouvrir sa fiche : PV, attaque, intention, passifs. Un toucher court sur un ennemi attaque toujours directement.": "<b>View a card</b>: press and hold a card (enemy or ally) to open its sheet: HP, attack, intent, passives. A short tap on an enemy always attacks directly.",
