  "<b>{0} récompenses</b> : Les Sept Péchés capitaux, Les Souverains infernaux, Les Pactes scellés, Deux cents sceaux, Premier ensemble<br>{e0}": "<b>{0} rewards</b>: The Seven Deadly Sins, The Infernal Sovereigns, The Sealed Pacts, Two Hundred Seals, First Set<br>{e0}",
