  "Allégés : moins de particules, ni secousses de caméra ni éclairs, décor sobre. À essayer si les combats saccadent.": "Light: fewer particles, no camera shake or flashes, plain scenery. Try it if combat stutters.",
  "Alors… le Néant peut perdre une enchère.": "So… the Void can lose an auction.",
