  "Ange déchu · Infernal": "Fallen angel · Infernal",
  "Anges": "Angels",
  "Anges et démons se haïssent : +{0} % de dégâts dans les deux sens.": "Angels and demons hate each other: +{0}% damage both ways.",
  "Anges, séraphins, gardiens du firmament et créatures lumineuses. Les Sept Cieux sont empilés comme les marches d’un escalier dont personne n’a vu le sommet depuis la Chute.": "Angels, seraphim, guardians of the firmament and creatures of light. The Seven Heavens are stacked like the steps of a stairway whose top no one has seen since the Fall.",
  "Annule les coups dangereux en gelant ou en ralentissant.": "Cancels dangerous attacks by freezing or slowing.",
  "Annule les premiers dégâts subis.": "Negates the first damage taken.",
  "Annuler": "Cancel",
