  "Aperçu Créateur · invisible pour les joueurs": "Creator preview · hidden from players",
  "Apogée": "Apex",
  "Appel aux armes": "Call to arms",
  "Apprenti bestiaire": "Apprentice bestiarist",
  "Appât des égarés": "Lure of the lost",
  "Après chaque combat gagné, l’équipe récupère {0} % de ses PV.": "After each fight won, the team recovers {0}% of its HP.",
  "Après le {0}e lot, on compte les points. Le plus de points gagne.": "After lot {0}, points are counted. Most points wins.",
  "Après les {0} poses, celui qui a le plus de cartes à sa couleur gagne.": "After {0} placements, whoever has the most cards in their color wins.",
  "Après les {0} poses, on compte les cartes de chaque couleur, plus celle restée en main (le score affiché pendant la partie compte déjà les cartes en main). À {1} contre {2}, celui qui tient la case centrale (le cœur du Sceau) gagne.": "After the {0} placements, count each color's cards, plus the one left in hand (the score shown during the game already counts cards in hand). At {1} to {2}, whoever holds the center square (the heart of the Seal) wins.",
  "Après ton premier gardien vaincu, chaque chapitre commence par un présage au choix parmi trois : un avantage et un prix pour tout le chapitre.": "After your first guardian is defeated, each chapter starts with an omen chosen from three: an advantage and a price for the whole chapter.",
  "Araignée de la forge": "Spider of the forge",
  "Araignée de la forge · Commune": "Spider of the forge · Common",
