  "Argentée": "Silvered",
  "Arrache des PV à la cible (plus d’une fois et demie sa force) et s’en nourrit. Chaque festin réussi lui donne +{0} ATQ (+{1} en phase {2}). Gel ou Brisure l’interrompent.": "Tears HP from the target (more than one and a half times its strength) and feeds on it. Each successful feast gives it +{0} ATK (+{1} in phase {2}). Freeze or Break interrupts it.",
