  "Bats d’abord l’adversaire précédent.": "Drive the previous opponent first.",
  "Bats ton premier gardien dans la Descente : il viendra ici. · force de l’étage {0}": "Beat your first guardian in the Descent: it will come here. · floor power {0}",
