  "Crée ton compte pour entrer dans l’Abysse : ta collection est sauvegardée en ligne, tu la retrouves sur n’importe quel appareil, et tu entres dans les classements.": "Create your account to enter the Abyss: your collection is saved online, you’ll find it on any device, and you join the leaderboards.",
