  "C’est au tour de Le Rêveur Sous la Fosse : « Caresse du vide » attaque et rapporte {0} PA": "The Dreamer Beneath the Deep's turn: “Void Caress” attacks and earns {0} AP",
  "C’est au tour de Lucifer, l’Étoile du Matin : « Lame ardente » attaque et rapporte {0} PA": "Lucifer, the Morning Star's turn: “Burning Blade” attacks and earns {0} AP",
  "C’est au tour de Métatron, la Voix du Trône : « Lame céleste » attaque et rapporte {0} PA": "Metatron, Voice of the Throne's turn: “Celestial Blade” attacks and earns {0} AP",
