  "Donne un nom à cette équipe.": "Give this team a name.",
  "Donne à une carte que tu possèdes sa finition suivante (argentée, puis enluminée, puis abyssale) contre des cendres. Tes favorites et ton équipe d’abord. Tu peux en sublimer <b>{0}</b> maintenant.": "Give a card you own its next finish (Silvered, then Illuminated, then Abyssal) for Ashes. Your favorites and your team first. You can exalt <b>{0}</b> now.",
  "Donne-lui un nom court, par exemple « Givre » ou « Anti-gardien ».": "Give it a short name, for example “Frost” or “Anti-guardian”.",
