  "La lumière juge. La lumière pardonne rarement.": "The light judges. The light rarely forgives.",
  "La lumière qui délivre": "The Delivering Light",
  "La lumière t’a guidé, cette fois.": "The light guided you, this time.",
  "La lumière vacille. Au centre de l’arène, un disque noir se lève, cerclé de feu.": "The light flickers. At the center of the arena, a black disc rises, ringed with fire.",
  "La lune prophétique": "The prophetic moon",
  "La légende polonaise dit qu’on le tua avec un mouton farci de soufre. Il a appris à se méfier des moutons.": "Polish legend says it was killed with a sheep stuffed with sulfur. It has learned to distrust sheep.",
  "La légende pragoise dit qu’un rabbin le modela pour protéger sa communauté. Effacer une lettre suffit à l’arrêter.": "Prague legend says a rabbi shaped him to protect his community. Erasing a single letter is enough to stop him.",
  "La légende provençale dit qu’une sainte l’apprivoisa avec de l’eau bénite. Les habitants l’ont achevée quand même.": "Provençal legend says a saint tamed it with holy water. The townsfolk finished it off anyway.",
  "La légende veut que saint Thomas d’Aquin l’ait brisé, agacé par ses bavardages. Les morceaux parlent encore.": "Legend has it Saint Thomas Aquinas smashed it, annoyed by its chatter. The pieces still talk.",
  "La machine qui parlait": "The machine that spoke",
  "La maison aux pattes de poule": "The house on chicken legs",
  "La maison gagne toujours.": "The house always wins.",
