  "La nuit dévore": "The night devours",
  "La nuit, elle laisse ses jambes derrière elle. Saupoudrez-les de sel et d’ail : elle ne pourra plus revenir.": "At night, she leaves her legs behind. Sprinkle them with salt and garlic: she will never come back.",
  "La page cachée": "The hidden page",
  "La page en trop. Il dort au fond de toutes les mers à la fois, et ses rêves prennent forme dans le monde éveillé.": "The page too many. It sleeps at the bottom of every sea at once, and its dreams take shape in the waking world.",
