  "La sagesse remontée": "Wisdom wound up",
  "La salle tremble sous une respiration de forge. Sept têtes se lèvent, et chacune te regarde.": "The room shakes under a breath like a forge. Seven heads rise, and each one looks at you.",
  "La sauvegarde a échoué : l’espace de stockage du navigateur est peut-être plein ou désactivé.": "Saving failed: the browser's storage may be full or disabled.",
  "La sauvegarde principale était abîmée : la copie de secours a été restaurée.": "The main save was damaged: the backup copy has been restored.",
  "La sentence ne se discute pas": "The sentence is not up for debate",
  "La sorcière aux huit bras": "The eight-armed witch",
  "La spirale parfaite": "The perfect spiral",
  "La suppression efface ton profil, ta sauvegarde en ligne et tes scores. Ta partie reste sur cet appareil.": "Deleting erases your profile, your online save and your scores. Your game stays on this device.",
  "La synchronisation était en pause.": "Sync was paused.",
  "La table est toujours mise": "The table is always set",
  "La terre qui dévore": "The devouring earth",
  "La tisseuse de la cascade": "The weaver of the waterfall",
  "La tradition chinoise dit qu’il n’apparaît qu’en temps de paix. On ne l’a pas vu depuis longtemps.": "Chinese tradition says it appears only in times of peace. It hasn’t been seen for a long while.",
  "La tradition persane dit que son ombre posée sur une tête la promet à la royauté.": "Persian tradition says that where its shadow falls on a head, that head is promised a crown.",
  "La tête qui vole": "The flying head",
  "La vengeance qui attend": "The vengeance that waits",
  "La vente": "The sale",
  "La vente est terminée.": "The sale is over.",
  "La vente n’est pas terminée.": "The sale isn't over.",
  "La victoire": "Victory",
  "La ville qui tousse": "The Coughing City",
  "La voie de gauche se gagne en jouant. La voie enluminée (à droite) se débloque une fois par saison avec des obsidiennes : seulement des cadres peints, des titres et des dos de cartes, jamais de puissance. Les cadres et dos marqués « Échoppe » s'achètent aussi à l'unité.": "The left path is earned by playing. The illuminated path (on the right) unlocks once per season with Obsidians: only painted frames, titles and card backs, never power. Frames and backs marked “Emporium” can also be bought individually.",
  "La vue lumineuse": "The luminous sight",
  "Lamashtu, Pazuzu et Tiamat : ensemble, +{0} ATQ et +{1} % de PV (+{2} ATQ à trois).": "Lamashtu, Pazuzu and Tiamat: together, +{0} ATK and +{1}% HP (+{2} ATK with three).",
  "Lame ardente": "Burning Blade",
  "Lame céleste": "Celestial Blade",
  "Lame de fond": "Undertow",
  "Lame de midi": "Blade of noon",
  "Lame-miroir": "Mirror-blade",
  "Lames affûtées": "Sharpened Blades",
  "Lance": "Spear",
  "Lance d’abord une Descente.": "Start a Descent first.",
  "Lance le pouvoir d’équipe.": "Unleash the team power.",
  "Lance une Descente pour pouvoir sauter d’étage.": "Start a Descent to be able to skip floors.",
  "Lancé au hasard": "Thrown at random",
  "Langue": "Language",
  "Lanterne de garde": "Watch lantern",
  "Lanterne des Noyés": "Lantern of the Drowned",
  "Laque rouge sang et filets d’or.": "Blood-red lacquer and gold filigree.",
  "Larmes de cire": "Tears of wax",
  "Le <b>Cauchemar</b> se joue sur un <b>chapitre déjà terminé</b> : ennemis plus forts, gardiens <b>déchaînés</b> dès le premier tour. Trois paliers (I, II, III) : chacun s’ouvre quand tu atteins l’étage {0} au palier précédent.<br><br>La difficulté s’ajoute au <b>plancher</b> de ton équipe : une équipe très forte affronte, dès le début, des ennemis aussi durs qu’un étage avancé en mode normal. La puce Cauchemar t’indique lequel.<br><br>En échange, chaque étage gagné pour la <b>première fois</b> à ce palier redonne sa récompense : plus d’éclats, et des coffres d’une qualité au-dessus.": "<b>Nightmare</b> is played on an <b>already completed chapter</b>: stronger enemies, guardians <b>unleashed</b> from the first turn. Three tiers (I, II, III): each opens when you reach floor {0} on the previous tier.<br><br>The difficulty adds to your team’s <b>baseline</b>: a very strong team faces, right from the start, enemies as tough as a deep floor in normal mode. The Nightmare chip tells you which one.<br><br>In return, each floor won for the <b>first time</b> on that tier grants its reward again: more Shards, and chests one quality higher.",
  "Le <b>bouton doré</b> lance la compétence de son rôle (Rempart, Coup d’estoc, Prière…). Elle coûte des <b>PA</b> : alterne attaques et compétences.<br><br>La <b>Ferveur</b> (losanges violets en bas) est commune à l’équipe : attaques, faiblesses, esquives, parades et Brisures la remplissent. Pleine ({0}), elle lance ton <b>pouvoir d’équipe</b>. Tu en gardes <b>{1} au plus</b> pour le combat suivant.": "The <b>golden button</b> casts its role’s skill (Bulwark, Thrust, Prayer…). It costs <b>AP</b>: alternate attacks and skills.<br><br><b>Fervor</b> (purple diamonds at the bottom) is shared by the team: attacks, weaknesses, dodges, parries and Breaks fill it. When full ({0}), it unleashes your <b>team power</b>. You keep <b>up to {1}</b> for the next battle.",
  "Le Bestiaire fut scellé par sept gardiens, un par royaume. Chacun posa sa main sur la reliure et promit de ne jamais l’ouvrir. Les livres anciens disent qu’un seul d’entre eux a menti. Ils ne disent pas lequel.": "The Bestiary was sealed by seven guardians, one for each realm. Each laid a hand on the binding and swore never to open it. The ancient books say that one of them lied. They do not say which.",
  "Le Bestiaire interdit a été déchiré. Ses créatures se cachent dans des boosters scellés. À toi de les retrouver, de les renforcer et de les mener au combat.": "The Forbidden Bestiary has been torn apart. Its creatures hide in sealed boosters. It’s up to you to find them, empower them and lead them into battle.",
  "Le Bestiaire interdit a été écrit par les premiers Scelleurs pour enfermer ce qui ne devait plus marcher sous le ciel. Une nuit, quelqu’un l’a déchiré. Ses pages se sont envolées dans les boosters scellés, et ses vingt chapitres sont tombés dans l’Abysse. Tu es le dernier à savoir lire les sceaux : descends, et referme-les.": "The Forbidden Bestiary was written by the first Sealers to lock away what must never walk beneath the sky again. One night, someone tore it apart. Its pages scattered into sealed boosters, and its twenty chapters fell into the Abyss. You are the last one who can read the seals: descend, and close them again.",
  "Le Bestiaire refermé": "The Bestiary closed",
  "Le Bourreau": "The Executioner",
  "Le Cauchemar": "Nightmare",
  "Le Cauchemar redonne ces coffres, d’une qualité au-dessus.": "Nightmare gives these chests again, one quality higher.",
  "Le Cauchemar se joue sur un chapitre que tu as déjà terminé.": "Nightmare is played on a chapter you've already finished.",
