  "Le Dragon garde l'Orient. Lui garde l'Occident, et il ne partage pas.": "The Dragon guards the East. He guards the West, and he does not share.",
  "Le Démon sans peau": "The Skinless Demon",
  "Le Dévoreur": "The Devourer",
  "Le Dévoreur a mangé la crypte qu’elle gardait. Elle est restée debout dans le noir, à garder ce qui n’existe plus, et sa rancune a remplacé ses os.": "The Devourer ate the crypt she guarded. She stayed standing in the dark, guarding what no longer exists, and her grudge replaced her bones.",
