  "Manticore, Entraveurs (Givre-venin).": "Manticore, Shacklers (Frost-venom).",
  "Manuelle": "Manual",
  "Manuelle : touche dans la zone dorée pour esquiver, sur le trait blanc pour une parade parfaite. Automatique : rien à toucher, mais seulement {0} esquives sur {1} et jamais de parade parfaite (moins de Ferveur et de PA).": "Manual: tap in the gold zone to dodge, on the white line for a Perfect Parry. Automatic: nothing to tap, but only {0} dodges out of {1} and never a Perfect Parry (less Fervor and AP).",
  "Marcheur des nuées": "Walker of the clouds",
  "Marque consommée !": "Mark consumed!",
  "Marque du chasseur": "Hunter's Mark",
  "Marque du chasseur, Brisure, Entraveurs.": "Hunter's Mark, Break, Shacklers.",
  "Marque un ennemi : le prochain coup d’une AUTRE de tes créatures fait +{0} % de dégâts et +{1} Brisure, puis la Marque part ({2} tours au plus). +{3} à tes jets de dés contre lui, et sa faiblesse est révélée.": "Marks an enemy: the next hit from ANOTHER of your creatures deals +{0}% damage and +{1} Break, then the Mark fades ({2} turns max). +{3} to your dice rolls against it, and its weakness is revealed.",
  "Marque, Brisure, poison qui affaiblit.": "Mark, Break, weakening poison.",
  "Marque, Brèche et Chaîne": "Mark, Breach and Chain",
  "Marque, cibles brisées.": "Mark, Broken targets.",
  "Marque, puis le coup d’une autre créature : +{0} % de dégâts et +{1} Brisure. Avec le Coup d’estoc : +{2} au jet en plus.": "Mark, then another creature's hit: +{0}% damage and +{1} Break. With Thrust: an extra +{2} to the roll.",
  "Marquis de la discorde": "Marquis of discord",
  "Marquis de la discorde · Peu commune": "Marquis of discord · Uncommon",
  "Marqué : le prochain coup d’une autre de tes créatures fait +{0} % et +{1} Brisure, +{2} aux jets de dés contre lui.": "Marked: the next hit from another of your creatures deals +{0}% and +{1} Break, +{2} to dice rolls against it.",
  "Marqué : le prochain coup d’une autre de tes créatures fait +{0} % et +{1} Brisure, puis la Marque part. +{2} aux jets": "Marked: the next hit from another of your creatures deals +{0}% and +{1} Break, then the Mark fades. +{2} to rolls",
