  "Merci, ton signalement a été envoyé. Ce joueur est masqué pour toi.": "Thank you, your report was sent. This player is hidden for you.",
  "Merci. Ce pseudo est maintenant masqué pour tout le monde.": "Thank you. This username is now hidden for everyone.",
