  "Mi-chemin. Les aiguilles des horloges reculent quand tu avances. Le gardien de ce chapitre a volé du temps aux Scelleurs, assez pour les voir vieillir et mourir. Il en a encore en réserve, et il compte bien s’en servir.": "Halfway. The clock hands turn back as you move forward. This chapter's guardian stole time from the Sealers, enough to watch them grow old and die. He still has some in reserve, and he fully intends to use it.",
