  "Mille ans de ruse. Elle a été impératrice, courtisane et pierre. Elle a préféré chacune de ces vies.": "A thousand years of cunning. She has been an empress, a courtesan and a stone. She preferred each of those lives.",
  "Mille bêtes, un seul corps. Toutes ont faim en même temps.": "A thousand beasts, one body. All of them hungry at once.",
