  "Mère de la Nuit · Mythique": "Mother of Night · Mythic",
  "Mère de la lune, des étoiles et du soleil. Elle les a tous mis au monde, elle peut tous les reprendre.": "Mother of the moon, the stars and the sun. She brought them all into the world; she can take them all back.",
  "Mère de mille dards": "Mother of a thousand stings",
