  "Mère des hivers éternels": "Mother of eternal winters",
  "Mère du Soleil, de la Lune et de l’Aurore. Elle a donné l’éclat à l’or et aux yeux.": "Mother of the Sun, the Moon and the Dawn. She gave gold and eyes their gleam.",
  "Méduse Funèbre, Entraveurs.": "Funeral Jellyfish, Shacklers.",
  "Méduse fut belle avant d’être maudite. Depuis, tout ce qui croise son regard devient pierre.": "Medusa was beautiful before she was cursed. Since then, all who meet her gaze turn to stone.",
  "Médée le vainquit en retirant le clou de sa cheville. Il a fait poser une serrure, depuis.": "Medea defeated him by pulling the nail from his ankle. He’s had a lock fitted since.",
