  "Même somme avec deux voisines ou plus : elles sont capturées. Puis le Combo continue, comme pour Identique.": "Same sum with two or more neighbors: they’re captured. Then the Combo continues, as with Same.",
  "Même ta dernière copie : la créature quitte alors ta collection (on te demande toujours de confirmer).": "Even your last copy: the creature then leaves your collection (you will always be asked to confirm).",
  "Même un moineau trouve ses graines !": "Even a sparrow finds its seeds!",
