  "Neuf jours de guerre entre les Sept Cieux et ceux qui les quittèrent. Les deux camps revendiquent la victoire. Les ruines des deux camps se ressemblent.": "Nine days of war between the Seven Heavens and those who left them. Both sides claim victory. The ruins of both sides look alike.",
