  "Plus assez de points d’action.": "Not enough action points.",
  "Plus bas, l’air gèle dans tes poumons. Une reine a offert son royaume à l’hiver pour qu’il ne change jamais, et le chapitre qui la tenait endormie est tombé à ses pieds. Elle ne veut pas te tuer : elle veut te garder.": "Further down, the air freezes in your lungs. A queen gave her kingdom to winter so it would never change, and the chapter that kept her asleep has fallen at her feet. She doesn't want to kill you: she wants to keep you.",
  "Plus chanceux que la moyenne.": "Luckier than average.",
  "Plus cruel que le kelpie, disent les Écossais. Ceux qui le montent ne descendent plus.": "Crueler than the kelpie, say the Scots. Those who ride him never get off.",
  "Plus dangereux : éclats doublés, {0} bonus au choix et un talent pour une de tes créatures.": "More dangerous: double shards, {0} bonuses of your choice and a talent for one of your creatures.",
