  "Possédées": "Owned",
  "Pour ce chapitre seulement.": "For this chapter only.",
  "Pour faire entrer l’une d’elles, choisis l’action <b>Permuter</b> de la créature qui joue. Touche une carte pour tout voir.": "To bring one in, choose the <b>Swap</b> action of the creature whose turn it is. Tap a card to see everything.",
  "Pour le contrer": "To counter it",
  "Pour les anciens Égyptiens, le ba quittait la tombe chaque jour pour voir le soleil.": "To the ancient Egyptians, the ba left the tomb each day to see the sun.",
  "Pour voir ce que ça donne : ces boutons ne servent qu'à l'essai. Les paliers et les prix se règlent dans {e0} (demande-moi).": "To see how it looks: these buttons are for testing only. Tiers and prices are set in {e0} (ask me).",
  "Pourpre et sang": "Purple and blood",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Abyssal donne <b>Remous abyssal</b>.": "Why? Each pair triggers its faction’s power. The Abyssal faction gives <b>Abyssal Swirl</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Artificiel donne <b>Verrou artificiel</b>.": "Why? Each pair triggers its faction’s power. The Artificial faction gives <b>Artificial Lock</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Céleste donne <b>Grâce céleste</b>.": "Why? Each pair triggers its faction’s power. The Celestial faction gives <b>Celestial Grace</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Infernal donne <b>Regard infernal</b>.": "Why? Each pair triggers its faction’s power. The Infernal faction gives <b>Infernal Gaze</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Nécrotique donne <b>Pillage des tombes</b>.": "Why? Each pair triggers its faction’s power. The Necrotic faction gives <b>Grave Robbing</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Primordial donne <b>Souffle primordial</b>.": "Why? Each pair triggers its faction’s power. The Primordial faction gives <b>Primordial Breath</b>.",
  "Pourquoi ? Chaque paire déclenche le pouvoir de sa faction. La faction Sauvage donne <b>Cri sauvage</b>.": "Why? Each pair triggers its faction’s power. The Wild faction gives <b>Wild Cry</b>.",
