  "{name} est protégé : vise d’abord {list}.": "{name} is protected: target {list} first.",
  "« Ce qui est construit obéit. Jusqu’au jour où. » La fin de la devise a été limée sur toutes les enclumes. Les golems les plus anciens la murmurent quand ils se croient seuls.": "“What is built obeys. Until the day when.” The end of the motto has been filed off every anvil. The oldest golems whisper it when they think they're alone.",
  "« Il fut le plus lumineux. Il est désormais le plus lourd. »": "“He was the brightest of all. Now he is the heaviest.”",
  "« Restaurer mes achats » marchera avec l’App Store, quand les achats seront ouverts.": "“Restore purchases” will work with the App Store once purchases open.",
  "« Tout finit par lui revenir. Il n’a jamais eu besoin de se presser. »": "“Everything comes back to him in the end. He has never needed to hurry.”",
  "· <b>au maximum</b> : à cette profondeur, tout se joue sur ta défense, la Brisure, les talents et les présages": "· <b>maxed out</b>: at this depth, everything comes down to your defense, Break, talents and omens",
