  "ABYSSAL peut t’envoyer une notification quand ton <b>booster gratuit du jour</b> t’attend, et avant la fin du délai quand c’est <b>à toi de jouer</b> contre un autre joueur.": "ABYSSAL can send you a notification when your <b>free daily booster</b> is waiting, and before time runs out when it's <b>your turn</b> against another player.",
  "Tu peux changer d’avis à tout moment : Réglages → Jeu → Notifications.": "You can change your mind anytime: Settings → Game → Notifications.",
  "Non merci": "No thanks",
  "Oui, me prévenir": "Yes, notify me",
  "Notifications": "Notifications",
  "Booster gratuit du jour (10 h) et rappel 2 h avant la fin du délai quand c’est à toi de jouer en ligne.": "Free daily booster (10 am) and a reminder 2 h before time runs out when it's your turn online.",
  "Notifications refusées : autorise-les dans les Réglages du téléphone → ABYSSAL → Notifications.": "Notifications refused: allow them in your phone's Settings → ABYSSAL → Notifications.",
  "Petites vibrations sur les coups, les victoires et les cartes rares. Dans l’app, le téléphone vibre vraiment ; sur le site web, l’iPhone ne vibre presque pas.": "Small vibrations on hits, victories and rare cards. In the app the phone really vibrates; on the website the iPhone barely vibrates.",
  "Tout révéler": "Reveal all",
  /* v522 : parties rapides et lentes */
  "En haut, « Contre un joueur » : affronte d’autres joueurs (au hasard ou un ami). Partie rapide : {0} s par coup, les deux joueurs connectés. Partie lente : {1} h par coup, chacun à son rythme. Coup pas joué à temps : partie perdue. Victoire : +{2} éclats et le classement du mois.": "At the top, “Against a player”: face other players (at random or a friend). Fast match: {0} s per move, both players online. Slow match: {1} h per move, each at their own pace. Move not played in time: match lost. Victory: +{2} shards and the monthly ranking.",
  "Choisis ta vitesse. Si tu ne joues pas ton coup à temps, <b>la partie est perdue</b>. La règle est tirée au hasard.": "Choose your speed. If you don't play your move in time, <b>the match is lost</b>. The rule is drawn at random.",
