  "Chacun joue quand il veut. Tu es prévenu quand c’est ton tour.": "Each player moves whenever they like. You're notified when it's your turn.",
  "Recherche en cours : la partie commence dès qu’un joueur arrive.": "Searching: the match starts as soon as a player arrives.",
  "Partie rapide · reste sur cet écran, la partie démarre dès qu’un joueur arrive.": "Fast match · stay on this screen, the match starts as soon as a player arrives.",
