  "Affronte d’autres joueurs : premier à 60 points.": "Face other players: first to 60 points.",
  "En haut, « Contre un joueur » : affronte d’autres joueurs (au hasard ou un ami), premier à {0} points. Partie rapide : {1} s par action, les deux joueurs connectés. Partie lente : {2} h par action, chacun à son rythme. Action pas jouée à temps : partie perdue. Victoire : +{3} éclats et le classement du mois.": "At the top, “Against a player”: face other players (at random or a friend), first to {0} points. Fast match: {1} s per action, both players online. Slow match: {2} h per action, each at their own pace. Action not played in time: match lost. Victory: +{3} shards and the monthly ranking.",
