  "Règles": "Rules",
  "<b>Recherche d’un adversaire…</b><small>Partie rapide · reste sur cet écran, la partie démarre dès qu’un joueur arrive.</small>": "<b>Looking for an opponent…</b><small>Fast match · stay on this screen, the match starts as soon as a player arrives.</small>",
