  "Contre un ami": "Against a friend",
  "<b>Contre un ami</b>{e0}": "<b>Against a friend</b>{e0}",
  "En haut, « Contre un ami » : défie un de tes amis. Pas de récompense ici, seulement ton bilan de victoires et de défaites contre chacun. Partie rapide : {0} s par carte ; partie lente : {1} h. Coup pas joué à temps : partie perdue.": "At the top, “Against a friend”: challenge one of your friends. No rewards here, only your win and loss record against each of them. Fast match: {0} s per card; slow match: {1} h. Move not played in time: match lost.",
  "Entre amis : pour le plaisir, et pour ton bilan contre chacun.": "Between friends: for fun, and for your record against each of them.",
  "Défie un ami. Chaque fois que c’est à toi, tu as un temps limité pour retourner tes cartes : passé ce délai, <b>la partie est perdue</b>.": "Challenge a friend. Each time it's your turn, you have limited time to turn your cards: after that, <b>the match is lost</b>.",
  "Entre amis seulement : pas de récompense, juste ton bilan contre chacun.": "Friends only: no rewards, just your record against each of them.",
