  "La voie de gauche se gagne en jouant. La voie enluminée se débloque une fois par saison avec des obsidiennes : seulement des cadres peints, des titres et des dos de cartes, jamais de puissance.": "The left path is earned by playing. The illuminated path is unlocked once per season with obsidians: only painted frames, titles and card backs, never power.",
