  "Une finition achetée se pose sur autant de cartes que tu veux, une par carte. Elle ne change rien à leurs valeurs.": "A finish you buy can go on as many cards as you like, one per card. It never changes their stats.",
  "<b>Pack du Fondateur</b> <small>Vendu une seule fois. Le cadre et le dos de cartes du Fondateur, le titre « Fondateur » (badge au classement) et {0} obsidiennes.</small>": "<b>Founder's Pack</b> <small>Sold only once. The Founder frame and card back, the “Founder” title (leaderboard badge) and {0} obsidians.</small>",
  "Pendant l'aperçu, tout achat en euros est simulé : aucun paiement. Rien ici ne rend tes créatures plus fortes.": "During the preview, every real-money purchase is simulated: no payment. Nothing here makes your creatures stronger.",
