  "Metatron": "Metatron",
  "<b>Esquive !</b>": "<b>Dodge!</b>",
  "Arrache des PV à la cible (plus d’une fois et demie sa force) et s’en nourrit. Chaque festin réussi lui donne +{0} ATQ (+{1} en phase {2}). Gel ou Brisure l’interrompent. Renforcée par ses serviteurs : +{3} %.": "Tears HP from the target (more than one and a half times its strength) and feeds on it. Each successful feast gives it +{0} ATK (+{1} in phase {2}). Freeze or Break interrupts it. Boosted by its servants: +{3}%.",
  "{e0}<b>Dévorer +{0} %</b><small>à son tour</small>": "{e0}<b>Devour +{0}%</b><small>on its turn</small>",
  "Dévorer +{0} %": "Devour +{0}%",
  "Syn.": "Syn.",
  "Empoisonnement : Frappe et empoisonne la cible (+{0} poison).": "Poisoning: Strikes and poisons the target (+{0} poison).",
