  "Dévorer !": "Devour!",
  "{e0}<b>Dévorer !</b>": "{e0}<b>Devour!</b>",
  "<b>Sa mécanique</b> Un tour sur deux, il rend un Verdict : à ton tour suivant, une action est interdite à toute ton équipe (attaquer, utiliser une compétence, ou se défendre).": "<b>Its mechanic</b> Every other turn, it delivers a Verdict: on your next turn, one action is forbidden to your whole team (attacking, using a skill, or defending).",
  "{e0}<b>À mi-vie : Sentence finale</b> Ses Verdicts tombent toujours un tour sur deux, et ses coups chargés frappent plus fort.": "{e0}<b>At half HP: Final sentence</b> Its Verdicts still fall every other turn, and its charged blows hit harder.",
